/// <reference types="@figma/code-connect/figma-types" />
import figma from 'figma';

// One template for all icons; per-icon data comes from icons.figma.batch.json
// (generated by scripts/generate-icon-code-connect.mjs).
export default {
  example: figma.code`<${figma.batch.name} />`,
  imports: [`import { ${figma.batch.name} } from '${figma.batch.importPath}';`],
  id: figma.batch.id,
  metadata: {
    nestable: true,
  },
};
